param([string]$BaseUrl="http://127.0.0.1:8000",[int]$ProjectId=1)
$ErrorActionPreference="Stop"
function S([string]$scope){Invoke-RestMethod -Method Post -Uri "$BaseUrl/api/v1/auth/local/demo-session" -ContentType "application/json" -Body (@{scope=$scope}|ConvertTo-Json -Compress)}
function P([string]$path,[hashtable]$body,[hashtable]$headers){Invoke-RestMethod -Method Post -Uri "$BaseUrl$path" -Headers $headers -ContentType "application/json" -Body ($body|ConvertTo-Json -Depth 12 -Compress)}
$hq=S hq;$agency=S agency;$client=S client;$hh=@{Authorization="Bearer $($hq.token)"};$ah=@{Authorization="Bearer $($agency.token)"};$ch=@{Authorization="Bearer $($client.token)"};$n=Get-Date -Format "yyyyMMddHHmmssfff";$root="/api/v1/factory-platform/projects/$ProjectId/citation-monitoring"
$m=P "$root/monitors" @{monitor_key="CITATION-$n";market="US";locale="en-US";model_provider="observed-provider";question_reference="BUYER-Q-$n"} $hh;$o=P "$root/monitors/$($m.id)/observations" @{observation_manifest=@{observed="bounded snapshot";observed_at=$n}} $hh;$o=P "$root/observations/$($o.id)/verify" @{expected_revision=$o.revision;reference="CITATION-VERIFY-$n"} $ah;$r=P "$root/observations/$($o.id)/releases" @{target="geo-owner";analysis_manifest=@{consumer="geo";automatic_content_change=$false;citation_or_ranking_guaranteed=$false}} $hh;$r=P "$root/releases/$($r.id)/approve" @{expected_revision=$r.revision;reference="CITATION-APPROVE-$n"} $ah;$r=P "$root/releases/$($r.id)/acknowledge" @{expected_revision=$r.revision;reference="CITATION-RECEIPT-$n"} $ch;[pscustomobject]@{monitor_status=$m.status;observation_status=$o.status;release_status=$r.status;release_available=$r.available;automatic_content_change=$false;citation_or_ranking_guaranteed=$false;hq=$hq.user.id;agency=$agency.user.id;consumer=$client.user.id}|ConvertTo-Json
